"""Bounded plotting data; charts are generated by the presentation layer."""
from .base import ProfilerComponent, SectionResult


class InteractionsComponent(ProfilerComponent):
    name = 'interactions'
    def update(self, batch):
        pass

    def finalize(self, results):
        c = self.context
        pairs = [(a, b) for a, b in c.pairs if c.roles[a] == c.roles[b] == 'numeric'] if c.config.interactions else []
        # Store one shared sample, not a separate DataFrame for every pair.
        return SectionResult(self.name, {'pairs': pairs, 'sample': c.sample if c.config.interactions else None},
                             {**c.sample_metadata(), 'enabled': c.config.interactions,
                              'missingness_matrix': 'derive from this sample, never draw every source row'})
